# Expected values are SymPy's outputs for the same calls (Galois groups and resolvents).

skip_unless_full_tests()

skip_on_cran()

.bt <- new.env(parent = asNamespace("symcompR"))
eval(parse(text = r"---(# Python str()/repr() of the values the battery compares.
x <- Symbol("x"); y <- Symbol("y")
X4 <- .gg_X(4); X5 <- .gg_X(5); X6 <- .gg_X(6)
pylist <- function(v) structure(v, class = "pylist")
seeded <- function(s, expr) { .py_seed(s); expr }
poly_str <- function(p) {
  gens <- vapply(p$gens[seq_len(.poly_ngens(p))], .str, "")
  paste0("Poly(", .poly_terms_str(p), ", ", paste(gens, collapse = ", "), ", domain='", .domain_of(p$rep), "')")
}
hist_loop <- function(T, k) {
  h <- new.env(); Tc <- .gg_coeffs(T); g <- T$gens[[1L]]
  pylist(lapply(seq_len(k), function(i) {
    r <- .gg_tsch(Tc, history = h)
    .gg_hist_add(h, r$U)
    sstr(up_to_expr(r$A, g))
  }))
}
chain <- function(T, k) {
  h <- new.env(); Tc <- .gg_coeffs(T); g <- T$gens[[1L]]; X <- Dummy("X")
  pylist(lapply(seq_len(k), function(i) {
    r <- .gg_tsch(Tc, history = h)
    Tc <<- r$U
    out <- sstr(up_to_expr(r$A, g))
    g <<- X
    out
  }))
}
py_repr <- function(v) {
  if (is.null(v)) return("None")
  if (inherits(v, "TransitiveSubgroupName")) return(.gg_name_repr(v))
  if (inherits(v, "galois_group_result")) return(format(v))
  if (inherits(v, "PermutationGroup")) return(format(v))
  if (inherits(v, "Permutation")) return(format(v, repr = TRUE))
  if (inherits(v, "Poly")) return(poly_str(v))
  if (is_sym(v)) return(sstr(v))
  if (inherits(v, "pylist")) return(paste0("[", paste(vapply(unclass(v), py_repr, ""), collapse = ", "), "]"))
  if (is.list(v)) {
    if (!is.null(names(v))) return(paste0("{", paste(names(v), vapply(v, py_repr, ""), sep = ": ", collapse = ", "), "}"))
    if (length(v) == 1L) return(paste0("(", py_repr(v[[1L]]), ",)"))
    return(paste0("(", paste(vapply(v, py_repr, ""), collapse = ", "), ")"))
  }
  if (is.character(v) && length(v) == 1L) return(paste0("'", v, "'"))
  if (is.logical(v) && length(v) == 1L) return(if (v) "True" else "False")
  if (length(v) == 1L) return(as.character(v))
  paste0("[", paste(as.character(v), collapse = ", "), "]")
}
py_str <- function(v) {
  if (inherits(v, "TransitiveSubgroupName")) return(format(v))
  if (is.character(v) && length(v) == 1L) return(v)
  if (inherits(v, "galois_group_result")) return(format(v))
  py_repr(v)
}
)---"), envir = .bt)
.run <- function(code) {
  e <- .bt
  NULL
  get("py_str", envir = .bt)(eval(parse(text = code), envir = e))
}
.setup <- function(code) invisible(eval(parse(text = code), envir = .bt))
.err <- function(code) tryCatch({ .run(code); "no error" }, error = function(e) conditionMessage(e))

test_that("Galois groups and resolvents match SymPy", {
  expect_equal(.run("galois_group(x, by_name = TRUE)"), "(<S1TransitiveSubgroups.S1: 'S1'>, True)")
  expect_equal(.run("galois_group(x^2 + x + 1, by_name = TRUE)"), "(<S2TransitiveSubgroups.S2: 'S2'>, False)")
  expect_equal(.run("galois_group(x^3 + x^2 - 2*x - 1, by_name = TRUE)"), "(<S3TransitiveSubgroups.A3: 'A3'>, True)")
  expect_equal(.run("galois_group(x^3 + 2, by_name = TRUE)"), "(<S3TransitiveSubgroups.S3: 'S3'>, False)")
  expect_equal(.run("galois_group(x^4 + x^3 + x^2 + x + 1, by_name = TRUE)"), "(<S4TransitiveSubgroups.C4: 'C4'>, False)")
  expect_equal(.run("galois_group(x^4 + 1, by_name = TRUE)"), "(<S4TransitiveSubgroups.V: 'V'>, True)")
  expect_equal(.run("galois_group(x^4 - 2, by_name = TRUE)"), "(<S4TransitiveSubgroups.D4: 'D4'>, False)")
  expect_equal(.run("galois_group(x^4 + 8*x + 12, by_name = TRUE)"), "(<S4TransitiveSubgroups.A4: 'A4'>, True)")
  expect_equal(.run("galois_group(x^4 + x + 1, by_name = TRUE)"), "(<S4TransitiveSubgroups.S4: 'S4'>, False)")
  expect_equal(.run("galois_group(x^5 + x^4 - 4*x^3 - 3*x^2 + 3*x + 1, by_name = TRUE)"), "(<S5TransitiveSubgroups.C5: 'C5'>, True)")
  expect_equal(.run("galois_group(x^5 - 5*x + 12, by_name = TRUE)"), "(<S5TransitiveSubgroups.D5: 'D5'>, True)")
  expect_equal(.run("galois_group(x^5 + 2, by_name = TRUE)"), "(<S5TransitiveSubgroups.M20: 'M20'>, False)")
  expect_equal(.run("galois_group(x^5 + 20*x + 16, by_name = TRUE)"), "(<S5TransitiveSubgroups.A5: 'A5'>, True)")
  expect_equal(.run("galois_group(x^5 - x + 1, by_name = TRUE)"), "(<S5TransitiveSubgroups.S5: 'S5'>, False)")
  expect_equal(.run("galois_group(x^6 + x^5 + x^4 + x^3 + x^2 + x + 1, by_name = TRUE)"), "(<S6TransitiveSubgroups.C6: 'C6'>, False)")
  expect_equal(.run("galois_group(x^6 + 108, by_name = TRUE)"), "(<S6TransitiveSubgroups.S3: 'S3'>, False)")
  expect_equal(.run("galois_group(x^6 + 2, by_name = TRUE)"), "(<S6TransitiveSubgroups.D6: 'D6'>, False)")
  expect_equal(.run("galois_group(x^6 - 3*x^2 - 1, by_name = TRUE)"), "(<S6TransitiveSubgroups.A4: 'A4'>, True)")
  expect_equal(.run("galois_group(x^6 + 3*x^3 + 3, by_name = TRUE)"), "(<S6TransitiveSubgroups.G18: 'G18'>, False)")
  expect_equal(.run("galois_group(x^6 - 3*x^2 + 1, by_name = TRUE)"), "(<S6TransitiveSubgroups.A4xC2: 'A4 x C2'>, False)")
  expect_equal(.run("galois_group(x^6 - 4*x^2 - 1, by_name = TRUE)"), "(<S6TransitiveSubgroups.S4p: 'S4+'>, True)")
  expect_equal(.run("galois_group(x^6 - 3*x^5 + 6*x^4 - 7*x^3 + 2*x^2 + x - 4, by_name = TRUE)"), "(<S6TransitiveSubgroups.S4m: 'S4-'>, False)")
  expect_equal(.run("galois_group(x^6 + 2*x^3 - 2, by_name = TRUE)"), "(<S6TransitiveSubgroups.G36m: 'G36-'>, False)")
  expect_equal(.run("galois_group(x^6 + 2*x^2 + 2, by_name = TRUE)"), "(<S6TransitiveSubgroups.S4xC2: 'S4 x C2'>, False)")
  expect_equal(.run("galois_group(x^6 + 10*x^5 + 55*x^4 + 140*x^3 + 175*x^2 + 170*x + 25, by_name = TRUE)"), "(<S6TransitiveSubgroups.PSL2F5: 'PSL2(F5)'>, True)")
  expect_equal(.run("galois_group(x^6 + 10*x^5 + 55*x^4 + 140*x^3 + 175*x^2 - 3019*x + 25, by_name = TRUE)"), "(<S6TransitiveSubgroups.PGL2F5: 'PGL2(F5)'>, False)")
  expect_equal(.run("galois_group(x^6 + 6*x^4 + 2*x^3 + 9*x^2 + 6*x - 4, by_name = TRUE)"), "(<S6TransitiveSubgroups.G36p: 'G36+'>, True)")
  expect_equal(.run("galois_group(x^6 + 2*x^4 + 2*x^3 + x^2 + 2*x + 2, by_name = TRUE)"), "(<S6TransitiveSubgroups.G72: 'G72'>, False)")
  expect_equal(.run("galois_group(x^6 + 24*x - 20, by_name = TRUE)"), "(<S6TransitiveSubgroups.A6: 'A6'>, True)")
  expect_equal(.run("galois_group(x^6 + x + 1, by_name = TRUE)"), "(<S6TransitiveSubgroups.S6: 'S6'>, False)")
  expect_equal(.run("galois_group(x)"), "(PermutationGroup([\n    (0)]), True)")
  expect_equal(.run("galois_group(x^2 + x + 1)"), "(PermutationGroup([\n    (0 1)]), False)")
  expect_equal(.run("galois_group(x^3 + x^2 - 2*x - 1)"), "(PermutationGroup([\n    (0 1 2)]), True)")
  expect_equal(.run("galois_group(x^3 + 2)"), "(PermutationGroup([\n    (0 1 2),\n    (2)(0 1)]), False)")
  expect_equal(.run("galois_group(x^4 + x^3 + x^2 + x + 1)"), "(PermutationGroup([\n    (0 1 2 3)]), False)")
  expect_equal(.run("galois_group(x^4 + 1)"), "(PermutationGroup([\n    (0 1)(2 3),\n    (0 2)(1 3)]), True)")
  expect_equal(.run("galois_group(x^4 - 2)"), "(PermutationGroup([\n    (0 1 2 3),\n    (0 3)(1 2)]), False)")
  expect_equal(.run("galois_group(x^4 + 8*x + 12)"), "(PermutationGroup([\n    (3)(0 1 2),\n    (1 2 3)]), True)")
  expect_equal(.run("galois_group(x^4 + x + 1)"), "(PermutationGroup([\n    (0 1 2 3),\n    (3)(0 1)]), False)")
  expect_equal(.run("galois_group(x^5 + x^4 - 4*x^3 - 3*x^2 + 3*x + 1)"), "(PermutationGroup([\n    (0 1 2 3 4)]), True)")
  expect_equal(.run("galois_group(x^5 - 5*x + 12)"), "(PermutationGroup([\n    (0 1 2 3 4),\n    (0 4)(1 3)]), True)")
  expect_equal(.run("galois_group(x^5 + 2)"), "(PermutationGroup([\n    (0 1 2 3 4),\n    (1 2 4 3)]), False)")
  expect_equal(.run("galois_group(x^5 + 20*x + 16)"), "(PermutationGroup([\n    (4)(0 1 2),\n    (0 1 2 3 4)]), True)")
  expect_equal(.run("galois_group(x^5 - x + 1)"), "(PermutationGroup([\n    (0 1 2 3 4),\n    (4)(0 1)]), False)")
  expect_equal(.run("galois_group(x^6 + x^5 + x^4 + x^3 + x^2 + x + 1)"), "(PermutationGroup([\n    (0 1 2 3 4 5)]), False)")
  expect_equal(.run("galois_group(x^6 + 108)"), "(PermutationGroup([\n    (0 1 2)(3 4 5),\n    (0 3)(1 5)(2 4)]), False)")
  expect_equal(.run("galois_group(x^6 + 2)"), "(PermutationGroup([\n    (0 1 2 3 4 5),\n    (0 5)(1 4)(2 3)]), False)")
  expect_equal(.run("galois_group(x^6 - 3*x^2 - 1)"), "(PermutationGroup([\n    (0 4 5)(1 3 2),\n    (0 1 2)(3 5 4)]), True)")
  expect_equal(.run("galois_group(x^6 + 3*x^3 + 3)"), "(PermutationGroup([\n    (5)(0 1 2),\n    (3 4 5),\n    (0 4)(1 5)(2 3)]), False)")
  expect_equal(.run("galois_group(x^6 - 3*x^2 + 1)"), "(PermutationGroup([\n    (0 4 5)(1 3 2),\n    (0 1 2)(3 5 4),\n    (5)(2 4)]), False)")
  expect_equal(.run("galois_group(x^6 - 4*x^2 - 1)"), "(PermutationGroup([\n    (0 2 4 1)(3 5),\n    (0 3)(4 5)]), True)")
  expect_equal(.run("galois_group(x^6 - 3*x^5 + 6*x^4 - 7*x^3 + 2*x^2 + x - 4)"), "(PermutationGroup([\n    (1 4 5 3),\n    (0 4)(1 5)(2 3)]), False)")
  expect_equal(.run("galois_group(x^6 + 2*x^3 - 2)"), "(PermutationGroup([\n    (5)(0 1 2),\n    (3 4 5),\n    (1 2)(3 5),\n    (0 4)(1 5)(2 3)]), False)")
  expect_equal(.run("galois_group(x^6 + 2*x^2 + 2)"), "(PermutationGroup([\n    (1 4 5 3),\n    (0 4)(1 5)(2 3),\n    (1 4)(3 5)]), False)")
  expect_equal(.run("galois_group(x^6 + 10*x^5 + 55*x^4 + 140*x^3 + 175*x^2 + 170*x + 25)"), "(PermutationGroup([\n    (0 4 5)(1 3 2),\n    (0 4 3 1 5)]), True)")
  expect_equal(.run("galois_group(x^6 + 10*x^5 + 55*x^4 + 140*x^3 + 175*x^2 - 3019*x + 25)"), "(PermutationGroup([\n    (5)(0 1 2 3 4),\n    (0 5)(1 2)(3 4)]), False)")
  expect_equal(.run("galois_group(x^6 + 6*x^4 + 2*x^3 + 9*x^2 + 6*x - 4)"), "(PermutationGroup([\n    (5)(0 1 2),\n    (3 4 5),\n    (0 5 2 3)(1 4)]), True)")
  expect_equal(.run("galois_group(x^6 + 2*x^4 + 2*x^3 + x^2 + 2*x + 2)"), "(PermutationGroup([\n    (5)(0 1 2),\n    (0 4 1 3)(2 5),\n    (0 3)(1 4)(2 5)]), False)")
  expect_equal(.run("galois_group(x^6 + 24*x - 20)"), "(PermutationGroup([\n    (5)(0 1 2),\n    (1 2 3 4 5)]), True)")
  expect_equal(.run("galois_group(x^6 + x + 1)"), "(PermutationGroup([\n    (0 1 2 3 4 5),\n    (5)(0 1)]), False)")
  expect_equal(.run("galois_group((x)/2, by_name = TRUE)"), "(<S1TransitiveSubgroups.S1: 'S1'>, True)")
  expect_equal(.run("galois_group((x^2 + x + 1)/2, by_name = TRUE)"), "(<S2TransitiveSubgroups.S2: 'S2'>, False)")
  expect_equal(.run("galois_group((x^3 + x^2 - 2*x - 1)/2, by_name = TRUE)"), "(<S3TransitiveSubgroups.A3: 'A3'>, True)")
  expect_equal(.run("galois_group((x^4 + x^3 + x^2 + x + 1)/2, by_name = TRUE)"), "(<S4TransitiveSubgroups.C4: 'C4'>, False)")
  expect_equal(.run("galois_group((x^5 + x^4 - 4*x^3 - 3*x^2 + 3*x + 1)/2, by_name = TRUE)"), "(<S5TransitiveSubgroups.C5: 'C5'>, True)")
  expect_equal(.run("galois_group((x^6 + x^5 + x^4 + x^3 + x^2 + x + 1)/2, by_name = TRUE)"), "(<S6TransitiveSubgroups.C6: 'C6'>, False)")
  expect_equal(.err("galois_group(Poly(0, x))"), "Constant polynomial has no Galois group.")
  expect_equal(.err("galois_group(Poly(1, x))"), "Constant polynomial has no Galois group.")
  expect_equal(.err("galois_group(Poly(x^7 + 1, x))"), "Polynomial must be irreducible and univariate over ZZ or QQ.")
  expect_equal(.err("galois_group(x^7 - 2)"), "Only polynomials up to degree 6 are supported.")
  expect_equal(.err("galois_group(1)"), "galois_group(1) failed without generators")
  expect_equal(.err("galois_group(x*y)"), "Polynomial must be irreducible and univariate over ZZ or QQ.")
  expect_equal(.err("galois_group(x^2 + y, x)"), "Polynomial must be irreducible and univariate over ZZ or QQ.")
  expect_equal(.err("galois_group(x^2 + 0.5)"), "Polynomial must be irreducible and univariate over ZZ or QQ.")
  expect_equal(.err("galois_group(x^3 + sqrt(S(2)), x)"), "factorization not supported over EX")
  expect_equal(.err("galois_group(x^3 - sqrt(S(2)))"), "Polynomial must be irreducible and univariate over ZZ or QQ.")
  expect_equal(.err("galois_group(x^8 + x + 1)"), "Polynomial must be irreducible and univariate over ZZ or QQ.")
  expect_equal(.err("galois_group(x^2 - 1)"), "Polynomial must be irreducible and univariate over ZZ or QQ.")
  expect_equal(.run("galois_group(2*x^3 + 1, by_name = TRUE)"), "(<S3TransitiveSubgroups.S3: 'S3'>, False)")
  expect_equal(.run("galois_group(x^3/3 + x/7 + 1)"), "(PermutationGroup([\n    (0 1 2),\n    (2)(0 1)]), False)")
  expect_equal(.run("galois_group(y^3 + 2)"), "(PermutationGroup([\n    (0 1 2),\n    (2)(0 1)]), False)")
  expect_equal(.run("galois_group(x^2 - 2, x, by_name = TRUE)"), "(<S2TransitiveSubgroups.S2: 'S2'>, False)")
  expect_equal(.run("galois_group(Poly(x^4 - 2, x), by_name = TRUE)"), "(<S4TransitiveSubgroups.D4: 'D4'>, False)")
  try(.run("galois_group(x^4 + 1, max_tries = 1)"), silent = TRUE)
  try(.run("galois_group(x^4 + 1, max_tries = 0)"), silent = TRUE)
