  expect_equal(.run("galois_group(x^4 + 1, max_tries = 2, by_name = TRUE)"), "(<S4TransitiveSubgroups.V: 'V'>, True)")
  try(.run("galois_group(x^6 + x^5 + x^4 + x^3 + x^2 + x + 1, max_tries = 2)"), silent = TRUE)
